def main():
    input = sys.stdin.read().split()
    idx = 0
    H = int(input[idx])
    idx += 1
    W = int(input[idx])
    idx += 1

    A = []
    for _ in range(H):
        row = list(map(int, input[idx:idx+W]))
        A.append(row)
        idx += W
    B = []
    for _ in range(H):
        row = list(map(int, input[idx:idx+W]))
        B.append(row)
        idx += W

    max_sum = (H + W - 1) * 80
    offset = max_sum
    valid_mask = (1 << (2 * max_sum + 1)) - 1

    dp = [[0] * W for _ in range(H)]

    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                d = A[i][j] - B[i][j]
                mask = 0
                mask |= (1 << (offset + d))
                mask |= (1 << (offset - d))
                mask &= valid_mask
                dp[i][j] = mask
            else:
                d = A[i][j] - B[i][j]
                abs_d = abs(d)
                new_mask = 0
                if i > 0:
                    prev_mask = dp[i-1][j]
                    shifted_left = prev_mask << abs_d
                    shifted_right = prev_mask >> abs_d
                    new_mask |= shifted_left | shifted_right
                if j > 0:
                    prev_mask = dp[i][j-1]
                    shifted_left = prev_mask << abs_d
                    shifted_right = prev_mask >> abs_d
                    new_mask |= shifted_left | shifted_right
                new_mask &= valid_mask
                dp[i][j] = new_mask

    final_mask = dp[H-1][W-1]
    min_abs = float('inf')
    for k in range(2 * max_sum + 1):
        if (final_mask >> k) & 1:
            s = k - offset
            if abs(s) < min_abs:
                min_abs = abs(s)
    print(min_abs)

