def main():
    N, K = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    max_bit = 40  # since K can be up to 1e12 which is 40 bits
    cnt = [0] * (max_bit + 1)
    for bit in range(max_bit + 1):
        for a in A:
            if (a >> bit) & 1:
                cnt[bit] += 1

    @lru_cache(maxsize=None)
    def dp(bit, tight):
        if bit == -1:
            return 0
        if tight:
            k_bit = (K >> bit) & 1
            max_val = 0
            # Try choosing 0
            contribution_0 = cnt[bit] * (1 << bit)
            new_tight_0 = tight and (0 == k_bit)
            res_0 = contribution_0 + dp(bit - 1, new_tight_0)
            max_val = max(max_val, res_0)
            # Try choosing 1 if allowed
            if k_bit == 1:
                contribution_1 = (N - cnt[bit]) * (1 << bit)
                new_tight_1 = tight and (1 == k_bit)
                res_1 = contribution_1 + dp(bit - 1, new_tight_1)
                max_val = max(max_val, res_1)
            return max_val
        else:
            contribution_0 = cnt[bit] * (1 << bit)
            contribution_1 = (N - cnt[bit]) * (1 << bit)
            return max(contribution_0 + dp(bit - 1, False), contribution_1 + dp(bit - 1, False))

    result = dp(max_bit, True)
    print(result)

